#!/usr/bin/env node
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../..');
const OUT = path.join(ROOT, 'output');
const BLOCK = '**** YD001 SOURCE BLOCK ****';
const ENG = '**** ENGLISH ****';
const END = '**** END BLOCK ****';

function patchFile(rel, slug, T) {
  const fp = path.join(OUT, rel);
  const s = fs.readFileSync(fp, 'utf8');
  const applied = new Set();
  const parts = s.split(BLOCK);
  const out = parts.map((block, i) => {
    if (i === 0) return block;
    const slugM = block.match(/^\s*slug: (.+)$/m);
    const seifM = block.match(/^\s*seif: (.+)$/m);
    const markerM = block.match(/^\s*marker: (.+)$/m);
    if (!slugM || slugM[1].trim() !== slug) return BLOCK + block;
    const seif = seifM[1].trim();
    const marker = markerM ? markerM[1].trim() : 'main';
    const key = `${seif}#${marker}`;
    if (!(key in T)) return BLOCK + block;
    const enStart = block.indexOf(ENG);
    const enEnd = block.indexOf(END);
    if (enStart < 0 || enEnd < 0) throw new Error(`ENGLISH/END missing: ${rel} ${key}`);
    const before = block.slice(0, enStart + ENG.length + 1);
    const after = block.slice(enEnd);
    const text = T[key].endsWith('\n') ? T[key] : T[key] + '\n';
    applied.add(key);
    return BLOCK + before + text + after;
  });
  const missing = Object.keys(T).filter((k) => !applied.has(k));
  if (missing.length) throw new Error(`Keys not found in ${rel}: ${missing.join(', ')}`);
  fs.writeFileSync(fp, out.join(''), 'utf8');
  console.log(`OK ${rel} (${applied.size} blocks)`);
}

// --- mechaber (10) ---
patchFile('siman_034/mechaber/part-001.txt', 'mechaber', {
  '1#main': `The law of a blow to the gargeret. In it are 10 seifim. If the gargeret was severed — the majority of its cavity in the place fit for slaughter or above this — it is forbidden.`,
  '2#main': `If it was punctured with a puncture that has a deficiency the size of an issur — forbidden; and if a strap was removed from it along its length — if when folded around it becomes like an issur — forbidden; and some say we are not expert in the measure of an issur; therefore we estimate it by the majority of the width of the cavity of the kaneh. {Rama: And according to what will be explained shortly — the measure of an issur is less than a majority; if so, one who is not expert should be lenient; therefore it appears he meant to say the majority of the width of the cavity of a bird's kaneh, which is less than an issur; and one who is not expert should declare treifah in every matter. (My humble opinion).}`,
  '3#main': `If punctured around its circumference with thin punctures adjacent to one another like the punctures of a sieve — if they have no deficiency they combine to a majority of its cavity; and if they have deficiency they combine to an issur — that if there is an issur in the punctures together with the intact portion between them — forbidden; and this is when the punctures are so close that there is not between puncture and puncture a full puncture; but if there is between them more than this measure — what is between them does not combine.`,
  '4#main': `In a bird, if punctured knafah-style — one cuts the punctured place and the wing and places it on the opening of the cavity of the kaneh; if there is enough to cover the majority of the kaneh — forbidden. {Rama: And if a gargeret of a bird was deficient — some say we estimate like a punctured knafah (Rif and Rambam); and some say we estimate the large according to its size and the small according to its smallness, proportionate to the measure that is in an animal as an issur (Rashi and Rosh and Rabbeinu Yerucham).}`,
  '5#main': `Some say that if it became indented like a door that was not removed but hangs and stands there like a door on the mouth of the window — since the door closes the opening, the indentation must be large enough that an issur can enter and exit through it — meaning more than an issur.`,
  '6#main': `Some say that if it was punctured with a puncture open through from both sides — even if the puncture is only wide enough that an issur can enter through its width — meaning the thickness of an issur — forbidden.`,
  '7#main': `If it split entirely along its length — even though nothing was lacking from it — forbidden; and if anything remained of it above and below in the place fit for slaughter — kosher, because whatever the neck stretches the crack closes and seals; therefore it heals.`,
  '8#main': `If punctured below the place of slaughter — in any amount — treifah.`,
  '9#main': `If one found a gargeret that was severed or deficient and it is not known whether it happened while alive (and cannot attribute that it happened because of slaughter, that he slaughtered in two places) (Beit Yosef in name of innovations of Rashba) — one cuts it in another place and compares whether they are equal — kosher; and if not — forbidden; and we compare only ring to ring or bar to bar, but not ring to bar nor bar to ring. {Rama: And we are not expert in examination and there is to declare treifah in every matter; and all these laws of puncture and deficiency in gargeret apply only when it is known that it is from illness (Beit Yosef and Orach Chaim general rule 51); but if it happened from a thorn or needle — for us who are not expert in examining the esophagus — treifah in every matter, for we are concerned perhaps the esophagus was punctured, which is no less than if the neck were soiled with blood as explained above siman 33.}`,
  '10#main': `The kaneh at its end, from where it enters under (the chest), splits and from there divides and becomes three heads — one inclines to the heart and one to the liver and one to the lung, and all three are treifah with any amount. {Rama: However, in the heart-kaneh, which is fat descending between the folds of the lung and the heart, it is usual to have small thin punctures — and these are their exits and are not called punctures — and kosher (Hagahot Ashiri chapter 1 and Rokeach and in Sha'arim sha'ar 31).}`,
});

// --- turei-zahav (3) ---
patchFile('siman_034/turei-zahav/part-001.txt', 'turei-zahav', {
  '1#_': `Or above this. But below the place of slaughter its puncture in any amount, as stated below.`,
  '2#א': `By the majority of the width of the cavity of the kaneh. The reason for this is that we derive even in a bird, whose life-force is small, that it is permitted if one folds it and places it on the width of the cavity of the kaneh, as stated in seif 3 — all the more so in an animal whose life-force is so great — so Rashba.`,
  '2#ב': `And according to what will be explained, etc. Meaning in seif 3: without deficiency it is lenient with a majority, and with deficiency it is stringent as an issur; and Rama's difficulty was that opposite the majority of the circumference the issur would be smaller than it, but opposite the majority of the width of the cavity of the kaneh the issur is larger than it. It is simple that this is not so — for a large measure covers whatever area of the width of the cavity, and fills it from what is in the line encircling the circumference of the kaneh; therefore Rama answered that here we deal with the cavity of a bird's kaneh. And Rashba's words do not imply this, for he did not mention a bird at all; and therefore Rama's difficulty was on the essential stringency below, that the intact portion combines with the punctures — for then it would be difficult for us to combine and estimate everything in the majority of the circumference as in punctures without deficiency; and why go here to leniency to estimate as an issur? I saw many force themselves to answer Rama's difficulty in other ways — not worthwhile to me; and it appears to my humble opinion there is no difficulty at all, for certainly we see that in a crack there is a difference between length and width: in length a crack does not harm even if very large, and in width it harms in the majority of the circumference of the kaneh — which is the severance of the gargeret, which is the halachic majority; but if there is deficiency in the puncture and in that deficiency there is part of the width and part of the length — the length side in it does not harm — what will you say? It harms at least from the side of the deficiency in it. Behold, in that deficiency the main damage is from the part of the width in it; and you wish to stretch it and make from it like a crack and measure it in the majority of the circumference of the kaneh — I say to you: stretch it along the length of the kaneh and it will not disqualify at all; therefore the Sages gave the measure of an issur — that if the entire deficiency is like an issur, which is more than the majority of the circumference, if you stretch it and make from it a crack in its width, nevertheless we require specifically this measure, since in truth the entire puncture is not in width but only with the part of the length it becomes so after you stretch it; therefore we declare treifah at this measure even though the majority of the circumference remains and a minority of it has a puncture with deficiency the size of an issur with the length; and therefore also at the end it works well for this reason — that there the punctures are on the circumference of the kaneh; therefore if they have no deficiency we estimate by its majority in its circumference, like other severance of gargeret that cracked one crack in its width in its majority — likewise these small cracks, and even though these small cracks are very long, nevertheless along the length of the gargeret we do not combine, only their width, for length does not harm at all; we consider only its width along whatever length; and if the majority of the circumference were intact — kosher; but if there is deficiency in these small punctures, then the deficiency causes you to estimate also all the length, since along all the length there is in it a part of the width and it harms in it — its law is like one large puncture was lacking, the measure of all these punctures with the intact portion between them, and its measure is like an issur, as above exactly; and the stringency here is that even though the majority of the circumference of the kaneh was not removed at all — treifah, since there is a cavity like an issur — behold this issur has no more stringency than the measure of the majority of the circumference, for both are one; except that the measure of majority is when there is no deficiency and you consider only the width of the cracks, not the length at all; and if there is deficiency you consider also the length, since there is deficiency in it; and nevertheless we do not say it is as though all of it is the measure of the width, but the Sages established that in a cavity like an issur there is disqualification from the side of its width as the measure of the majority of the circumference; but in less than an issur — kosher even if there is a measure of majority if you stretch it. And therefore they said well: one who is not expert in the measure of an issur should be stringent to estimate by the majority of the circumference; and the stringency here is that in a puncture with deficiency we consider the entire deficiency as though it were for its width — treifah is found even if the deficiency in the cavity is less than an issur — clear to my humble opinion after I descended to the depth of the matter with heavenly aid and proposed the matter before great ones and it was pleasing in their eyes.`,
});

// --- beer-hagolah (10) ---
patchFile('siman_034/beer-hagolah/part-001.txt', 'beer-hagolah', {
  '1#_': `Mishnah there Chullin daf 42.`,
  '2#_': `From that incident that came before Rav, etc. there daf 44. (°) Meaning to exclude below, as below seif 8.`,
  '3#_': `There in the mishnah and like Rashbag.`,
  '4#_': `Statement of Rabbah bar bar Chanah, etc. there daf 45.`,
  '5#_': `Rashba in his chiddushim there (in name of Ba'al HaItur).`,
  '6#_': `Statement of Rav Yehudah, etc., and as R' Chelbo explains, etc. there.`,
  '7#_': `Rosh and Ran there.`,
  '8#_': `Ran there (and likewise implied in Rashi's explanation).`,
  '9#_': `Statement of R' Yitzchak bar Nachmani there.`,
  '10#_': `Statement of Rav Nachman; and per Rashi there and Tosefta there; and likewise Rashba in Tur HaGadol and Rabbeinu Yerucham.`,
});

// --- beur-hagra (7) ---
patchFile('siman_034/beur-hagra/part-001.txt', 'beur-hagra', {
  '2#א': `Therefore we estimate, etc. For even in a bird it is kosher — all the more so in an animal whose life-force is greater.`,
  '2#ב': `And according to what, etc. Meaning in Shulchan Aruch regarding a bird "if," etc., and in the hagahah he wrote "and if," etc., and "some say we estimate," etc. — and this is the view of the Rosh, who wrote: in the bird's question what is the difficulty? Only regarding knafah — for if we estimate it also according to its size, it would disqualify with a little; hence an issur is less than a majority.`,
  '3#א': `That if there is, etc. As stated regarding a bird: "one folds it," etc. — hence with the intact portion between them we estimate.`,
  '3#ב': `And this, etc. As the measure of adjacency of sieve punctures; and regarding a sieve we are established. Rashi.`,
  '4#א': `And if it was deficient, etc. As Rif explains in a bird: what? — if the entire deficiency of the bird's gargeret.`,
  '4#ב': `And some say, etc. As Rashi and Rosh explain: there is no difficulty except regarding knafah; but in deficiency it is like all measures of treifot — we estimate, etc.`,
  '9#_': `And he cannot, etc. As stated above s.k. 1.`,
});

// --- baer-heitev (17) ---
patchFile('siman_034/baer-heitev/part-001.txt', 'baer-heitev', {
  '1#א': `cavity. And Shach wrote: but the majority of the thickness of the wall of the kaneh does not complete to a majority — for the wall of the kaneh is thick from above and at the side of the neck it is only a thin membrane, and it is not forbidden until the majority of the cavity is severed; and the thickness of the wall does not complete to a majority (there). And likewise if severed from below upward so that there is a majority of its cavity — even though the majority of the thickness remains — treifah (Maharam Tit).`,
  '1#ב': `forbidden. And Shach wrote: it becomes nevelah; and do not challenge — for we have established above siman 24 seif 15 regarding ikur that even if only a minority remains connected in one place it is kosher — there we deal where the sign was not uprooted except from its place of connection in the jaw; therefore it is not treifah in a majority; but here, since the defect is in the body of the sign itself — therefore in a majority it is treifah; but below the place of slaughter its puncture in any amount.`,
  '2#_': `matter. And Shach and Taz disagree on this; and Shach holds it implies in every bird and animal in its own kaneh he speaks; and Rama's difficulty — Shach answers in another matter; and Taz also answers Rama's difficulty in another matter; and rules likewise that one must estimate in an animal by the majority of the cavity of the animal; and in Knesset HaGedolah he left the matter in safek.`,
  '3#א': `cavity. And Shach explains: specifically that it was punctured around its circumference exactly like this; but punctures that have no deficiency along the length of the kaneh do not combine to the majority of the circumference — for it would only be as though it split; therefore punctures without deficiency never disqualify except when they stand on the circumference of the gargeret in its majority; but punctures with deficiency apply only when standing in the middle or along the length of the gargeret — for on the circumference, even without deficiency, they disqualify. And therefore the Mechaber's wording is ambiguous: he opened "if punctured around its circumference — if they have no deficiency," etc., and "if they have deficiency," etc. — implying that with deficiency also refers to around the circumference — and this is not so; and it must be said thus: if they have no deficiency — then it is not treifah on a slight circumference except we require that the kaneh encircle it in its majority; but if there is deficiency — if there is an issur in the punctures — treifah even though they do not encircle the majority but some punctures stand on the circumference and some along the length — for it is possible when there are many punctures the size of an issur that they encircle a little of the kaneh — end of his words.`,
  '3#ב': `forbidden. And Shach explains: that if there is in it like an issur — even though it is not on the majority of the circumference of the kaneh — treifah; and with this Rama's difficulty is answered — what he challenged in the previous seif: that in truth the majority of the cavity is less than an issur; and that which we require — if there is deficiency in it — it is not treifah unless there is in it like an issur — because it does not stand on the majority of the cavity; and so Taz wrote.`,
  '3#ג': `combine. And Shach wrote: it implies from the Mechaber's words — since he did not write this law above — that in punctures without deficiency the intact portion between them does not combine even if there is not between puncture and puncture a full puncture; and it also implies there is no distinction between animal and bird regarding combining the intact portion — only in punctures with deficiency: even in an animal the intact portion combines to an issur when there is not between puncture and puncture a full puncture; and when there is no deficiency — even in a bird the intact portion does not combine to the majority of its gargeret's circumference.`,
  '4#א': `forbidden. And Shach explains: we estimate with the intact portion when there is not between puncture and puncture less than a full puncture — specifically in punctures with deficiency; but in punctures without deficiency — then the intact portion between them does not combine; and we estimate also in a bird by the majority of the circumference of its kaneh.`,
  '4#ב': `as an issur. And Shach explains: regarding knafah puncture all agree we estimate by the majority of the kaneh; but deficiency in one place — Shach holds we estimate the large according to its size; and it is explained in the Rosh's words that likewise everywhere we estimate in an animal — such as deficiency of the skull as a sela in siman 30, and likewise removal of the liver where we require two olives remain in an animal as below siman 41 seif 2 — we estimate in a bird according to the proportion of the measure in an animal.`,
  '5#_': `issur. And Shach wrote: for us, since we do not know the measure of an issur — we estimate by if it covers the majority of the kaneh, both in animal and bird.`,
  '6#_': `forbidden. And Shach wrote: the law is likewise both in animal and bird — not as the poskim who hold the law is specifically in a bird.`,
  '7#_': `heals. And Shach wrote in name of Beit Yosef and Maharshal: even if something remained above — all the more in a place not fit for slaughter, meaning above the large ring — it does not help and it is forbidden; and all the more below the place of slaughter.`,
  '8#_': `treifah. And the reason: from there onward it is judged as lung; and see above siman 20 what is called below the place of slaughter.`,
  '9#א': `places. And Shach wrote: it implies from Rama's words that if it can be attributed that because he slaughtered in two places it happened — we attribute even in deficiency; and even though above siman 24 seif 19 — if a ring is found on the knife, etc. — nevertheless we say every safek in slaughter is invalid; even if the ring was cut from one side — it must be said: perhaps here we deal where the ring was not lacking but two half-rings stuck to one another with the skin between them — for it is not the normal way that rings are cut in two around their circumference and connected together by the connecting skin; but certainly with the knife in the way of slaughter that went back and forth it happened, and through rolling of the gargeret they were cut in two around their circumference; or here we deal where the gargeret was lacking in a curve like this; or the skin between the rings was lacking; or when they stretch the kaneh the deficiency happens opposite the cut of the skin — as implied explicitly from Rashba's words that in such a case we attribute to the knife — end; since so it is, there is proof it happened from the knife; nevertheless with difficulty there is to permit in such a case — who knows to stretch properly.`,
  '9#ב': `matter. And Shach wrote: likewise in siman 36 regarding lung; and even to wrap ten and to compare we do not do likewise. And in Sefer Efi Ravrevi he wrote: if there is still some side to permit — we may be lenient through examination. But all the acharonim are stringent not to compare in any matter — and such is the custom. And we do not compare a ring of this animal to another animal (Derishah).`,
  '9#ג': `illness. And Shach wrote: likewise when he grasped the kaneh alone in a manner that he knows certainly he did not touch the esophagus; and see end of siman 21 and siman 23 seif 30.`,
  '10#א': `to the liver. Meaning the large duct in the liver; but regarding small ducts see siman 41.`,
  '10#ב': `and kosher. And the reason: they are mouths of the ducts and not punctures; and therefore if there are punctures there not in the place of the mouths of the ducts — treifah.`,
});

// --- siftei-kohen (22) ---
patchFile('siman_034/siftei-kohen/part-001.txt', 'siftei-kohen', {
  '1#א': `["If the gargeret was severed — the majority of its cavity."] The wall of the kaneh is thick from above and at the side of the neck it is only a thin membrane, and it is not forbidden until the majority of the cavity is severed; and the thickness of the wall of the kaneh does not complete to a majority — so it is in the Talmud and the poskim.`,
  '1#ב': `["Or above this."] Meaning above the place fit for slaughter as well — the law is thus that the gargeret is severed in its majority; and that which was stated above in siman 24 seif 15 and Taz on ikur — that even if only a minority remains connected in one place it is kosher — there we deal where the sign was not uprooted except from its place of connection in the jaw; but here, since the defect is in the body of the sign itself — in a majority it is treifah; but below the place fit for slaughter will be explained in this siman seif 8 that in any amount it is treifah.`,
  '1#ג': `["It is forbidden."] Bach's view: for Rambam, if the gargeret was severed in its majority and was not slaughtered — it is only treifah from life; and when slaughtered it becomes nevelah; and this is as stated in siman 33 s.k. 4 — see there.`,
  '2#_': `Therefore we estimate it by the majority of the width of the cavity of the kaneh. Thus Rashba: and it appears that nevertheless if the measure of the indentation is not more than half the round width of the opening of the kaneh — kosher; and as we say regarding a bird: one folds it and places it on the opening of the kaneh — if it covers the majority of the kaneh — treifah; and if not — kosher; hence in a bird whose life-force is small we go by the majority of the opening of the kaneh — all the more in an animal whose life-force is great — end of his words. And what the Rosh wrote: "and according to what will be explained shortly," etc. — meaning what is written in the seif after: "if punctured around its circumference," etc. — "if they have no deficiency they combine to a majority of its cavity," and "if they have deficiency they combine to an issur" — hence the measure of an issur is less than a majority; and likewise explicitly in Darkei Moshe; and so Derishah explained; therefore it appears to the Rosh that he meant the width of the cavity of a bird's kaneh; but this is very forced and does not appear to me at all — for it implies in every bird and animal in its own kaneh he speaks; and furthermore from Rashba's language it implies in an animal's kaneh he speaks; and furthermore Rashba wrote there like the mishnah (daf 54a) "until how much may it be deficient" — dealing explicitly with an animal; and furthermore if we deal with the majority of the cavity of a bird's kaneh — we still do not know its measure, which bird we estimate; and they wished to explain and did not succeed except to conceal; but certainly we deal with the width of the cavity of an animal's kaneh (meaning large for large and small for small). And regarding what the Rosh challenged — "and according to what will be explained shortly," etc. — to my humble opinion certainly the measure of an issur is more than the majority of the circumference of the animal's gargeret; and this is sensible to the sense of sight — for it is in any case larger than a bird's gargeret, as Rashi, Rosh, Ran, and other poskim wrote regarding a bird that there is not in its gargeret like an issur — see there; and in the majority of the circumference of the gargeret it is only one strap from punctures like this (and in an issur there are many such straps — except where punctures have no deficiency we never combine to a majority except when standing around the circumference like this) — in a matter that if you join them together the majority of the gargeret would be severed; but when standing along the length of the kaneh like this — even if the strap is so long as the majority of the circumference of the gargeret — they do not combine to a majority, for they are not connected together; certainly no less than split in seif 7 — that even if only something remained above and below — kosher (and see Kesef Mishneh chapter 3 of Hilchot Shechitah law 23 "if punctured punctures," etc.). But in punctures that have deficiency — combination applies only when standing along the length or in the middle of the gargeret; for when standing on the circumference of the gargeret it is obvious they combine to a majority — certainly no less than punctures without deficiency; and we derive nothing from "if they have deficiency" except that certainly what combines in punctures with deficiency to an issur is when standing along the length or in the middle of the gargeret in a matter that does not encircle the majority of the kaneh; and therefore to my humble opinion — even though a majority is less than an issur, as stated, and as implied somewhat from Rashi (daf 45a) "hence since," etc., until "and regarding punctures requires an issur to estimate them" — see there — nevertheless without deficiency it is treifah since they stand on the circumference of the gargeret — which is literally as though severed if you join them; but with deficiency — necessarily we deal when along the length of the kaneh, as explained; and combination of a majority does not apply, for they do not stand on the circumference; and therefore when treifah in punctures with deficiency — necessarily the reason is not severance but as though deficient; and therefore they combine to the measure of deficiency — meaning an issur, which is more than the majority of the cavity of the kaneh; and as I wrote it is proven from Rabbeinu Yerucham's words: some wrote that if it is a large bird and in its kaneh there is like an issur — we estimate it as an issur like in an animal; and some say a bird whose life-force is not so great as an animal — we do not estimate it as an issur even if in its width there is like an issur, but we estimate by a majority; and the first view appears primary — end; and Beit Yosef brings it; and since he wrote a bird's life-force is not so great, etc. — implies the measure of an issur is more than if it covers a large bird; and all the more it is more than the majority of its gargeret's circumference; and nevertheless he wrote the first view is primary — meaning in punctures with deficiency that combine to an issur in a large bird; and in punctures without deficiency he admits that even in a large bird they combine to a majority; if so, punctures without deficiency would be more stringent than punctures with deficiency — but certainly punctures without deficiency apply only when standing on the circumference of the gargeret, and punctures with deficiency only in the middle of the gargeret or along its length, as explained; and so it appears from other poskim' words, as explained. And in Hagahot Rama he wrote: and now that we are not expert in an issur how much it is — we estimate by the width of the cavity of the kaneh; and also in an animal we estimate thus — that if the punctures between them cover the cavity of the opening of the kaneh — treifah; and likewise piercing one long puncture — we estimate the deficiency of the strap also at this measure — end; and Rama omitted the hagahah of the Rosh; and perhaps he intended what I wrote. And what Bach wrote in seif 8 on this — I did not descend to the end of his mind in all his words — see there.`,
  '3#א': `["If punctured around its circumference," etc.] Meaning specifically punctured around the circumference exactly like this; but punctures without deficiency along the length of the kaneh do not combine to the majority of the circumference — for it would only be as though split; therefore punctures without deficiency never disqualify except when standing on the circumference of the gargeret in its majority — so too Rosh: punctures without deficiency combine to a majority if standing on the circumference of the gargeret — end; but punctures with deficiency apply only when standing in the middle or along the length of the gargeret — for on the circumference, even without deficiency, they disqualify, similar to severance; and we derive nothing from "if they have deficiency." And therefore the Mechaber's wording is ambiguous: he opened "if punctured around its circumference — if they have no deficiency," etc., and "if they have deficiency," etc. — implying with deficiency also refers to around the circumference; and Tur's wording is more ambiguous: he wrote "and if punctured around its circumference thin punctures adjacent to one another like sieve punctures — if they have deficiency they combine to an issur — that if there is an issur in the punctures with the intact portion between them — treifah; and if they have no deficiency — the measure is a majority" — until here his language; and therefore it must be said thus: "and if punctured around its circumference" — then the law is thus: if there is an issur in the punctures, etc. — treifah even though they do not encircle the majority but some punctures stand on the circumference and some along the length — for it is possible when there are many punctures the size of an issur that they encircle a little of the kaneh; and if they have no deficiency — then it is not treifah on a slight circumference except we require encircling the kaneh in its majority; and so interpret the Mechaber's words — and understand.`,
  '3#ב': `["And if they have deficiency," etc. — "that if there is an issur in the punctures with the intact portion between them," etc.] From that he wrote regarding punctures with deficiency — "if there is an issur in the punctures with the intact portion between them," etc. — and did not likewise write at the beginning regarding punctures without deficiency that the intact portion between them also combines to a majority — implies he holds in punctures without deficiency the intact portion does not combine even if there is not between puncture and puncture a full puncture; and it also implies from the Mechaber's words there is no distinction between animal and bird regarding combining the intact portion — only in punctures with deficiency: even in an animal the intact portion combines to an issur when there is not between puncture and puncture a full puncture; and when there is no deficiency — even in a bird the intact portion does not combine to the majority of its gargeret's circumference; and so I proved in my books that this is the view of Rashi, Rashba, Rosh, Tur, and Rabbeinu Yerucham.`,
  '4#א': `["In a bird, if punctured," etc.] Meaning punctures with deficiency — whose measure in an animal is like an issur, and in a bird there is not in its gargeret like an issur; and if we estimate according to the proportion of the measure of an issur in an animal — its measure of deficiency would be very small; and when the intact portion between them also combines — there would be a great stringency; therefore its measure is "if it covers," etc.; but in punctures without deficiency — since we require they stand on the circumference of the gargeret — there is no distinction between animal and bird, for always each one combines the majority of its gargeret's circumference — so Rosh and Rabbeinu Yerucham.`,
  '4#ב': `["And one places it on the opening of the cavity of the kaneh," etc.] Implies the intact portion between them also combines when there is not between puncture and puncture a full puncture; nevertheless this is specifically in punctures with deficiency — in an animal we estimate as an issur and in a bird by if it covers; but in punctures without deficiency — then the intact portion between them does not combine, as stated in s.k. 6; and we estimate also in a bird by the majority of the circumference of its kaneh.`,
  '4#ג': `["And some say we estimate the large," etc.] Regarding knafah puncture all agree we estimate by if it covers — for when the large is estimated according to its size, etc., and the intact punctured portion is considered — its measure of deficiency would be very small, as in s.k. 6; but in deficiency in one place — always we estimate the large according to its size and the small according to its smallness; and it is explained in the Rosh's words that likewise everywhere we estimate in an animal — such as deficiency of the skull as a sela in siman 30, and likewise removal of the liver where we require two olives remain in an animal as below siman 41 seif 2 — we estimate in a bird according to the proportion of the measure in an animal (and we deal with a bird that was slaughtered on the ground and checked and found the brain membrane was not punctured — nevertheless if the puncture is so large according to the proportion of the measure of a sela in an animal — treifah; and see siman 30 and examine).`,
  '5#_': `Meaning more than an issur, etc. See Rabbeinu Yerucham and Beit Yosef on this; and since for us it makes no difference — for also according to Rashi and Rosh, since we do not know the measure of an issur — also in indentation we estimate by if it covers, both in animal and bird — I shortened.`,
  '6#_': `Some say that if punctured with a puncture open through, etc. From Rif and Rambam's words it appears we deal with a bird, as explained in Beit Yosef; nevertheless it appears the law is likewise in an animal according to them — that if punctured open through from both sides we estimate as the thickness of an issur; except they came to explain we should not say specifically in an animal, but in a bird its measure is by if it covers, which is smaller than two thicknesses of an issur, as Kesef Mishneh wrote in chapter 3 of Hilchot Shechitah: if it covers less than the measure of two thicknesses of an issur — nevertheless in a bird we do not say "if it covers" but only wide enough for the thickness of an issur to enter through the two punctures; and the same in an animal — if indented we estimate wide enough that an issur can enter in its thickness through the two open punctures; and so it is proven from Tur's words that for Rif and Rambam the law is likewise; and Kesef Mishneh challenged Tur and his intent: since Rif and Rambam wrote this law regarding a bird — their view is not in an animal; and so in Darkei Moshe; and what he wrote is clear.`,
  '7#א': `["And if something remained," etc.] Bach challenged the Mechaber that this law depends on variant texts, etc. — see there; and to my humble opinion — even according to the text "some say," etc. — it may be explained: one authority — R' Yochanan — did not say "anything above and below" but R' Yonatan said so; and they said thus before R' Yochanan in name of R' Yosi; and R' Yochanan said: they know, etc., and they praised R' Yonatan — see there; and nevertheless Rif, Rambam, Rashi, Rashba, Rosh, Rabbeinu Yerucham, and all hold like the Mechaber; and Maharshal in chapter 1 siman 10 upholds the Mechaber's method.`,
  '7#ב': `["Above and below in the place fit for slaughter," etc.] Beit Yosef wrote: specifically to exclude a place not fit for slaughter below; but a remainder to the side above — even in a place not fit for slaughter — helps, for in that place it is not disqualified except in a majority — end; and so Peri To'ar and Bach wrote: but Rambam in chapter 3 of Hilchot Shechitah wrote: if split along its length — even if nothing remained of the place fit for slaughter in it except something above and something below — kosher, etc. — until also in Shulchan Aruch he retracted and wrote like Rambam's language — end; and I do not know what retraction is here — for on the contrary he intended and was precise and wrote opposite Rambam's words: Rambam wrote "even if nothing remained of the place fit for slaughter except something above," etc. — implies explicitly he also refers to something above near the place fit for slaughter; and the Mechaber wrote the opposite — and it implies thus: if something remained above in whatever place it remained — for there his puncture is not in any amount; and something below in the place fit for slaughter — kosher; nevertheless regarding the law, Maharshal's view there is also that even above the large ring it does not help; and see siman 20 s.k. 1.`,
  '8#א': `["Below the place of slaughter," etc.] See siman 20 what is called below the place of slaughter in bird and animal.`,
  '8#ב': `["In any amount — treifah."] For from there onward it is judged as lung to forbid puncture, as below in seif 10.`,
  '9#א': `["And cannot attribute that because of slaughter," etc.] Implies that if one can attribute that because he slaughtered in two places it happened — we attribute even in deficiency; and even though above siman 24 seif 19 — if a ring is found on the knife — nevertheless we say every safek in slaughter is invalid; even if the ring was cut from one side — it may be said: perhaps here we deal where the ring was not lacking but two half-rings stuck together with the skin between them — for it is not normal that rings are cut in two around their circumference and connected by connecting skin; but certainly with the knife in the way of slaughter it happened, and through rolling of the gargeret they were cut in two; or here we deal where the gargeret was lacking in a curve; or the skin between the rings was lacking; or when stretching the kaneh the deficiency happens opposite the skin cut — as Rashba states explicitly that in such a case we attribute to the knife — see there; since so it is, there is proof from the knife; nevertheless with difficulty there is to permit — who knows to stretch properly.`,
  '9#ב': `["Only ring to ring," etc.] Thus Tur: bar chulya is half a ring downward from where they begin to be thin; and some say chulya is the ring and bar chulya is the skin between the rings; and it is good to heed both views — end. And Rashi wrote chulya is three rings — so too Rosh.`,
  '9#ג': `["And we are not expert in examination."] Likewise regarding healthy lung in siman 36 seif 5 that we are not expert in such examination — see there. And in Sefer Efi Ravrevi he wrote: however if there is still some side to permit — one may be lenient through examination.`,
  '9#ד': `["When it is known that it is from illness."] Or that he grasped the kaneh alone in a manner he knows certainly he did not touch the esophagus — so Beit Yosef; and see end of siman 21 and siman 23 s.k. 15.`,
  '10#א': `["One inclines to the heart."] And this is the large duct that goes out from it to the lung.`,
  '10#ב': `["And one to the liver."] Meaning the large duct in the liver — and it is called the great hepatic duct; but the small ducts in the liver will be explained in siman 41; and likewise the small ducts in the lung in siman 36 seif 6.`,
  '10#ג': `["It is usual to have small thin punctures," etc.] And Beit Yosef wrote: I heard the reason that those veins are mouths of the ducts and are not punctures — end; and Darkei Moshe brings it; and hearing is not like seeing — for I saw with my eyes and it is simple; and therefore if there are punctures not in the place of the mouths of the ducts — treifah.`,
});

// --- kereti (21) ---
patchFile('siman_034/kereti/part-001.txt', 'kereti', {
  '1#א': `Majority of its cavity — for the wall of the kaneh is very thick, one side more than its fellow; and if you join the thickness of the wall it is less than the majority of its cavity.`,
  '1#ב': `Forbidden — and this is more severe than ikur uprooted from its place of connection, for here the loss is in the kaneh itself; and therefore it is nevelah.`,
  '2#א': `By the majority of the width of the cavity of the kaneh — this is Rashba's view in his chiddushim; and he learned: since we say regarding a bird "one folds it and places it on the opening of the kaneh" — likewise in an animal. And see Peleti where I expanded on this to clarify Rashba.`,
  '2#ב': `According to what will be explained shortly — Shach and Taz did not understand Rama's intent except Ben Shach in Knesset HaGedolah who explains Rama's intent on what is stated in seif 4 — specifically knafah puncture places on the kaneh and not in deficiency where the measure is greater; and see Peleti what I wrote in its answer.`,
  '2#ג': `Declare treifah in every matter — see Peleti that the measure of half the width of its cavity is certainly kosher — see there.`,
  '3#א': `If they have no deficiency — the acharonim wondered why the measure is smaller in punctures without deficiency that suffice with the majority of the circumference of the kaneh, while with deficiency an area of issur is required — that if you cut it to thin straps many encirclements of the kaneh result; see Shach and Taz who explain that with deficiency, even when standing along the length of the kaneh, it is not so as without deficiency — only on the circumference; but along the length of the kaneh — behold it only split along its length and is kosher; and see Peleti what is difficult in their words and on what I wrote the difference between deficiency and no deficiency in a proper answer — see there.`,
  '3#ב': `To an issur — meaning even a narrow issur — and not like Rambam in explanation of the mishnah who permits a narrow issur; see Peleti what I wrote.`,
  '3#ג': `And this is when the punctures, etc. — meaning with deficiency the intact portion combines; but without deficiency the intact portion does not combine — so agree the Mechaber and acharonim — not like Peri Chadash; see Peleti.`,
  '4#א': `Enough to cover — meaning with the intact portion between them as a full deficiency — only with deficiency.`,
  '4#ב': `Forbidden — and for us who do not know the measure of an issur — also in an animal, in knafah puncture one folds it and places it on its kaneh like in a bird; see Peleti.`,
  '4#ג': `And some say we estimate — this is the Rosh's view who holds the Sages gave this measure specifically in knafah puncture — otherwise the intact portion would combine; and then its measure would be very small; but in one-place deficiency — not so; and see Peleti.`,
  '5#א': `Hanging and standing — this is Rashi's explanation on the Talmud's question: "opened like a door."`,
  '5#ב': `Meaning more than an issur — and this is in an animal; but in a bird we estimate according to proportion for this "some say" in Shulchan Aruch; see Peleti.`,
  '6#א': `Open puncture — this is Rif's explanation on "opened like a door"; and see Peleti that the Mechaber adopts Rashi as primary and is stringent to heed Rif's view — see there.`,
  '6#ב': `As the thickness of an issur — see Peleti that one may say this is in bird and animal according to proportion.`,
  '7#_': `Fit for slaughter — and Maharshal's view to be stringent that a remainder is required below the large ring.`,
  '8#_': `In any amount — for from there its law is as lung.`,
  '9#א': `In two places — see above on this in siman 24.`,
  '9#ב': `And we are not expert — and in Sefer Efi Ravrevi he wrote: where there is still some side to permit — one may rely on this examination; and perhaps his view was broad to distinguish and compare as Shulchan Aruch states; but woe to us — our eyes are darkened and we do not really know to distinguish between tekhelet and karti; especially in such a matter requiring great examination — in a small matter it changes in a moment, God forbid, to combine any adjacency.`,
  '9#ג': `From illness — or it is clear to him he did not hit the esophagus — Shach.`,
  '9#ד': `For we are concerned perhaps the esophagus was punctured — implies from this even in a known place we are not expert in examination — not like Shach above; and so acharonim.`,
});

// --- peleti (5) ---
patchFile('siman_034/peleti/part-001.txt', 'peleti', {
  '2#א': `A puncture that has deficiency — Shach, Taz, and Peri Chadash wondered: behold the majority of the circumference of the kaneh is only a slight thing that has length and no width of a mere line encircling it; but an issur has length and width; and if you cut it to straps the circumference from a small coin in great length results, as the diagram printed in Shach — go read in it; and if so, how is without deficiency more stringent than with deficiency when its measure is smaller? See Shach and Taz who divide regarding the position of punctures — if on the circumference or along the length: along the length it is only as split and kosher, unlike with deficiency — whether on circumference or along length, with an issur — treifah. And one must understand according to their explanation the gemara that challenges: on "if punctured knafah" — why do they not combine to an issur? And Tosafot on "it was omitted" explained according to one view we deal with punctures with deficiency like knafah; and nevertheless what is the difficulty — perhaps we deal standing on the circumference and not along the length — and then it is obvious they combine to a majority; and the language knafah implies circumference as Rashi wrote. Also we say in the gemara: "a strap was removed from it" — they combine to an issur — Tur explains along its length; and it is difficult — behold the mishnah teaches deficiency as an issur; therefore necessarily along its length — for in its width an issur is not needed according to their words; and Tur's language "on the circumference" is difficult to fit them, as Shach himself. And it appears simply: certainly what is kosher in slaughter disqualifies in severance or removal; and see above siman 21 — if slaughtered in the kaneh in one place and finished in a second place — if not on one side like this and it is a majority — kosher; and if so likewise if severed like this — if it is a majority — treifah; but if slaughtered on one side like this — slaughter does not help and we do not say if combined along the length it is a majority — for the majority of the kaneh remains; and what is it to us if in that place it was cut once or many times one after another? And if so likewise in severance in such a case they do not combine to a majority — for the majority of the kaneh was not severed; but this is only in severance without deficiency — treifah not from severance of the kaneh but from deficiency; therefore there is no difference in whatever manner — treifah. And if so — "if punctured knafah" teaches: punctures on the circumference of the kaneh one below another like this — certainly if you take the amount of punctures and cut to straps and combine — behold here is the majority of the circumference; but you cannot combine — for the puncture like this is full of cracks like this and only the upper line combines, for the other lines are one below another and do not render treifah, as above; and the upper line alone is not a majority; therefore the issur Shach drew on the issur page — you have only an upper line, for the other lines and stretched straps are one under another and do not combine to the circumference as stated; and therefore kosher until punctures stand like this — that if you take only the upper line alone, nevertheless the majority of the circumference results — treifah. Unlike if the punctures amount to an issur — we say all punctures combine, not the upper line alone — for we do not render treifah from severance but from deficiency; and behold before you what I wrote — if side by side or one below another — and to my humble opinion. All is correct and clear; length here is unnecessary — only set your eyes on what I wrote and matters will clarify.`,
  '2#ב': `And according to what will be explained shortly, etc. — the acharonim did not understand Rama's intent until the great rabbi son of Shach in Nekudat HaKesef explained Rama's words well — for his intent is on the Rosh who explains in the bird's question: "if punctured knafah" — if the intact portion between them combines, and also proportionate to an issur in an animal its measure is very small; and on this the gemara says "one folds it," etc. — hence this measure is greater than that measure of an issur; and therefore Rama challenged well that he wrote to be lenient — see there. And regarding Rashba who brought this law in chiddushim — no difficulty, for he refers to Rif's words who brought this question on the bird regarding the mishnah teaching deficiency of kaneh as an issur, and therefore asked on a bird; and he answers "one folds it," etc. — and certainly we estimate according to proportion as the Rosh wrote; and then the proportion of an issur in a bird is like an issur in an animal; and nevertheless it suffices by folding and placing on the opening of the kaneh — hence both are one measure; and all the more if we come to answer the Rosh's difficulty on Rif — why not ask on all measures regarding a bird? — for it is obvious we estimate according to the proportion of a large ox; if so, likewise for puncturing the kaneh — only say: in all types of treifot there is no essential difference between animal and bird except one is large and one small, and it is obvious we estimate according to the animal's own proportion — ox, kid, and tender lamb, large and small, all by proportion; but in the kaneh of an animal — if the kaneh alone was slaughtered — slaughter helps, for life does not depend on it alone; but in a bird — if the kaneh alone was slaughtered — slaughter helps, for life goes out; and hence in the kaneh alone life depends; how compare animal treifot regarding kaneh to bird treifot where life goes out with severance of the kaneh much more than in an animal? And the gemara challenged and answered well: in truth in a bird they gave the measure of "one folds it," etc.; and if so it is proven it is a small measure proportionate to an issur — for otherwise on the contrary, what reason to be stringent in a bird you would be lenient. And therefore Ba'al HaItur's words that Rashba brought in his name are correct. But Rama's difficulty on the Mechaber who cites in Shulchan Aruch like the Rosh that the bird's question refers to knafah puncture — if so he should not have concealed like Rashba; and it may be said the Mechaber certainly holds even the Rosh agrees both are one measure — for otherwise the Rosh should have challenged Rif briefly: how lenient in a bird to give a measure greater than the proportion of an issur? And if so it was tradition from the Sages that the measure of "if it covers," etc., was transmitted to a bird — it is obvious there is no place for the Rosh's wonder why he asked on a bird regarding puncturing the kaneh and not other treifot where he did not know there is reason to distinguish; for certainly from the outset we estimate everything by proportion as the Rosh wrote; but regarding knafah he knew there is tradition that a bird has another measure — therefore he asked what the measure is; and he answered "one folds it," etc.; and to my humble opinion — nevertheless one may learn from the Rosh's words who explains like Rashi that the question on a bird refers to knafah puncture — meaning he knew that in a bird we estimate by animal proportion a very small measure of deficiency; we are not stringent at such a small measure to combine the intact portion with the very small deficiency; and he answers: no — the Sages gave another measure, etc. And it is asked: if the law of the judgment is to estimate by proportion and the intact portion between them combines — destined to be deficient — what of it if very small or large? So is God's perfect Torah to render treifah as it is, small or large; and a small amount renders treifah; and more wondrous that he answers they gave another measure — do they have mercy in judgment because its measure is small and easily treifah? They gave another measure to be lenient against the law of judgment — we never heard such in treifot; and it is forced to say combining the intact portion is only a rabbinic stringency and "they said, they said" to be lenient — this is forced; and if so its stringency is its leniency; therefore it appears certainly if the measure came according to the law of deficiency — and a matter rendered treifah in utmost smallness and minority we do not heed — what of it if it is small? So the Torah-giver gave in His straight and righteous statutes — only to estimate in a bird by animal proportion in these measures of sela, issur, olive, and the like, to make an almost precise proportion; in almost all of these I found no one who knows these measures on earth — only since impossible to aim precisely, we are stringent to minimize the measure utterly until doubt leaves our heart that this is certainly the proportionate measure relative to an animal — for such are our obligations and such is good for us; and therefore he did not ask on any treifot of sela, olive, and the like; but regarding deficiency in gargeret — where anyway we are stringent to combine the intact portion between them, destined to rot and congeal — one need not combine two stringencies; and to congeal one need not combine two stringencies of the intact portion mentioned to be stringent in the proportionate measure from lack of knowledge — if so it would be very heavy until a small puncture renders treifah; therefore they answered: what can be done with combining the intact portion — only from proportionate deficiency, and do not combine to be more stringent; and here there is another measure — "one folds it," etc.; and with this no estimation and proportionate measure is needed until you must be stringent; and if there is stringency from the intact portion between them — we do not heed, since the law of judgment is so. And this is clear in the Rosh's words; and if so it is proven the measure of "one folds it" is one measure with an issur — for otherwise how would they transgress the law to give another measure to be lenient against Torah law? Or one measure; and the leniency is only in knafah puncture so as not to need to be stringent in the proportion of the issur, as stated — for in this "one folds it," etc., its measure is understood. And therefore Rashba's words are stated for all; but with all this my heart wavers — for we do not know how much an issur is; and we say simply it is small; and in Berakhot until one sees an issur opposite his heart — meaning a small coin placed on the ground — if it does not sink much the sight will not fall on it; nevertheless there is to reject — who knows, perhaps relative to another coin it is small, and nevertheless essentially it is large — only this is to be precise in the measure of sela, which is more than an issur as known, and the measure of sela is one-third tefach as above end of siman 21 for one view — and it is proportionate to a finger and a half; and the eye saw and testified in the animal in its kaneh — one can insert several thumb-widths in the width; therefore examine the law. And more it appears Rashba holds what we see in a bird — "one folds it," etc. — and the sense testifies it is larger than an issur, as stated — that both are in tradition from the Sages: the cavity, majority of width of the kaneh we require without doubt, for the essence of treifah depends on majority in severance of the gargeret — this on the circumference and this on the width; only sometimes in a small animal the kaneh is small and the measure of covering the majority of the width of the kaneh is small — they gave the measure of an issur: if there is not in it an issur, even though it covers the majority of the width — nevertheless kosher; and both are required; and therefore in an animal we estimate as an issur — even though sometimes it does not cover the majority of the kaneh; nevertheless they were stringent and gave the measure of an issur; but in a bird, difficult to estimate by proportion — the measure of covering the kaneh remains; and understand; and examine the law — for Rashba himself was in doubt and did not decide for practical halachah. And from the Rosh's words we learn: if in the punctures and intact portion there is not enough to cover half the majority of the width of the cavity of the kaneh — certainly kosher; for the Rosh wrote: all the stringency is since the intact portion between them combines; and if the punctures and intact portion cover the majority of the width of the kaneh — the punctures alone cover half the majority of the width of the kaneh; for the intact portion between them is only like a full puncture; and if half the majority of the width of the kaneh is more than the proportion of an issur — still difficult is what is stated here regarding a bird that we do not estimate by proportion; and if here we are stringent to combine the intact portion — without the intact portion from here the punctures alone do not cover more than half the majority of the width of the kaneh, and it is more than an issur — and still you permit the forbidden at the measure of an issur; therefore it must be said this half is certainly less than an issur and permitted for all; only the intact portion between them that combines causes another measure — and understand, for this is clear.`,
  '3#א': `The intact portion between them — Shulchan Aruch's view: in punctures without deficiency the intact portion between them does not combine — not like Ran; and Shach wrote thus is the view of Rashi, Rashba, Tur, Rosh; and Peri Chadash wishes to be stringent like Ran; and one should not reject Shulchan Aruch's words, especially since for Rambam the intact portion does not combine — meaning in punctures with deficiency; and it appears this is Rif's view; and therefore he explains the question on a bird refers to the mishnah: a puncture deficient like an issur — and uproots the question from its place stated on knafah puncture and attaches it elsewhere on that mishnah; and this is the reason he holds: if knafah puncture — how does he say "one folds it and places it," etc. — behold there is intact portion between them and there is no covering to render treifah, for the intact portion does not combine; and therefore Rif explains it on that mishnah: deficient in one like an issur — and for this "one folds it" applies well, for there is no intact portion inside; and covering of the kaneh testifies how much was deficient — examine.`,
  '3#ב': `Forbidden — and we say in the gemara: an issur is like more than an issur; and the gemara inferred: "and ad" is not included; and therefore all ruled a narrow issur is treifah and does not permit except when less than an issur; and nevertheless Rambam in explanation of the mishnah wrote explicitly a narrow issur is kosher; and Peri Chadash already wondered; and one must force that Rambam explains the gemara thus: the issur stated in the mishnah does not refer to this issur that is kosher — only the mishnah's intent teaching "like an issur" means more than an issur itself is kosher; and the gemara inferred: therefore he holds "ad" and "ad" are not included — for if in Hillel's view how can one say the mishnah teaching "until how much may it be deficient — until an issur" means more than an issur, and "ad" is included? If so, much would enter — everything is included in "more"; and there is no limited measure; or "ad" is not included; and if so, whatever is more than an issur is not in the leniency and nothing is permitted except a narrow issur — and these are Rambam's words — and understand.`,
  '5#_': `Hanging and standing, etc. — this is Rashi; but Rif explains as stated in the next seif — open puncture; and if so one wonders on the Mechaber who brought two views together — if this is not that; and it must be said he adopts Rashi as primary — open puncture and issur in its thickness like Rif; one who remembers my name was not mentioned in the mishnah at all; and therefore he ruled like Rashi — since the indentation still stands we require a spacious issur; but this open puncture — no reason to forbid, for thickness of issur was not mentioned; and nevertheless he is concerned for Rif's words since they emerged from his mouth, and an unattributed ruling also to forbid; but the essence is Rashi's explanation; and therefore he permits when the opening hangs and stands — it is forbidden only when a spacious issur enters and exits. And it appears Rif follows his method that he holds the bird's question refers to deficiency like an issur — impossible to estimate in a bird as an issur, as above; and the Sages gave another measure to cover the majority of the cavity of the kaneh; and still difficult in indentation like a door in a bird — what? — so that an issur enters spaciously — behold in a bird there is no measure of issur at all; therefore Rif explains open puncture so that an issur enters in its thickness — and this is possible even in a bird that issur-thickness exists in reality in a bird like an animal; and to my humble opinion — unlike Rashi who explains in a bird on knafah puncture, but in issur-deficiency we estimate by proportion as the Rosh wrote; if so likewise in indentation like a door we estimate by proportion — and understand. And in truth one must understand: why in all matters we estimate in animal and bird everything according to large and small, and here in issur-thickness in indentation like a door animal and bird would be equal in measure as implied from poskim and Shach; therefore Rif and Rambam considered this measure said regarding a bird — and from this the opposite: in an animal more is required and the proportion is inverted — examine.`,
});

// --- mateh-yehonatan (2) ---
patchFile('siman_034/mateh-yehonatan/part-001.txt', 'mateh-yehonatan', {
  '1#_': `(Siman 34 seif 2) Therefore we estimate it by the majority of the width of the cavity of the kaneh. See Shach s.k. 4 — it appears from his words he wishes to explain Rama's difficulty is on puncture without deficiency — we estimate by a majority, and with deficiency — as an issur; and I challenged him on what he challenged — see there; and I say it certainly never entered Rama's mind; rather his difficulty is thus: behold some say Beit Yosef the Mechaber is Rashba's view, and proved so from Rif's explanation who explained in a bird: what? — it does not refer to knafah puncture but to deficiency — since the entire kaneh in a bird is not like an issur, how do we estimate? — and he answers: one folds it and places it on the opening of the kaneh; hence it is proven the measure of an issur is larger than if it covers; and this is certainly Rif's view that we estimate the large according to its size and the small according to its smallness; and impossible that the measure of an issur is smaller than if it covers — how does he say we estimate by if it covers — there would be greater stringency? If so Rama's difficulty is thus: behold the Mechaber ruled below seif 4 like Rashi and Rosh — how does he say here we estimate by the majority of the width of the cavity? Hence there is no place for Shach's difficulty; but nevertheless Rama's difficulty may be answered: for one may say according to Rashi and Rosh who hold the intact portion between them is as though it does not exist — if so, since the measure of an issur is so with if it covers, we do not estimate the large according to its size and the small according to its smallness — how is he lenient with the measure of an issur — immediately treifah; and it is forced to say they hold combining the intact portion is only rabbinic and "they said, they said"; if so the Rosh must also hold the measure of an issur is greater than if it covers; and if so the measure of if it covers would be smaller — if so also here impossible to stand; one may say what the Rosh wrote "impossible to stand" — certainly if each comes to be stringent and render treifah in puncture — all the more he says we estimate by if it covers, which is a known limited measure; and so Shach siman 55 explains the Rosh's words thus; if so Rama's difficulty is nothing — for even though the Mechaber explains like Rashi and Rosh, nevertheless one may say the measure of an issur is greater than if it covers; and according to this it is proven from the Rosh's words that the Rosh holds also if it covers is greater than an issur; if so that which he challenges Rif — and further "what is my difficulty here more than other issurim," etc. — he should have challenged: since he estimated issur is small — what does he say we estimate by if it covers — behold it would come to be lenient — if only as an issur it is immediately treifah; and he answers he did not wish to challenge thus; one may say Rif holds it is halachah to Moses at Sinai thus in a bird: if deficient like an issur it is not treifah until deficient like the measure of if it covers, etc.; if so the Rosh still does not challenge why "what is my difficulty here more," etc. — because other cases he knows we estimate large according to size, etc.; but here the measure of issur was not transmitted to a bird at all — therefore he wonders on a bird; if so the Rosh must also hold the measure of issur is greater than if it covers; and he holds the measure of issur was transmitted to a bird — therefore he challenges well according to R' Eliezer: what is my difficulty, etc. But this may be said according to Rashba: behold an issur is smaller than a sela, and a sela is one-third tefach — seven-thirds of fingers; if so the measure of issur is less than this; how does he say the measure of an issur is greater than if it covers? And this sensible sight contradicts — for behold our eyes see the width of the opening of the kaneh in a large ox is width of nearly four fingers; and one may say Rashba holds according to Rif that two measures were transmitted to Moses: if its majority covers — it is greater — we estimate by if it covers; and if an issur is greater than if it covers — we estimate by an issur; and to answer the Rosh's difficulty on Rif he had to explain thus — for otherwise difficult: why wonder here more than other issurim; and according to what is required on a bird — this measure was also transmitted to a bird — if so we estimate the large according to its size — only the measure of an issur; or one view: it was not transmitted to a bird at all — we estimate by if it covers; and he says we estimate by if it covers because the measure of an issur was not transmitted at all to a bird.`,
  '2#_': `(Shulchan Aruch seif 5) And some say if indented like a door, etc. One may say from what the Mechaber wrote in the seif — it is Rashi's explanation from that which the Talmud says "became indented like a door" — meaning since the indentation still stands, a somewhat larger measure than if removed from it is required; and what the Mechaber wrote in the seif after — is Rif's explanation on "opened like a door"; if so the Mechaber gives credit to two parties for one leniency; and it must be said he adopts Rif as primary — therefore if open puncture one requires thickness like an issur; and nevertheless he is concerned for Rashi's view stringently — that even if the indentation still stands, if an issur enters and exits — treifah.`,
});

// --- nekudot-hakesef (2) ---
patchFile('siman_034/nekudot-hakesef/part-001.txt', 'nekudot-hakesef', {
  '1#_': `(Siman 34 seif 2 in hagahah) Measure of an issur. In Rambam's explanation of the mishnah in chapter 2 of Chullin — an issur is four grains of barley and its thickness as fit and its form round; and in chapter 1 of Kiddushin daf 10 — a sela is four dinarim and a dinar is twenty-four issurim; hence an issur is one ninety-sixth of a sela; and a sela is one-third tefach — meaning three date-pits; and so in siman 48 and Siftei Kohen siman 30 s.k. 8 — see there.`,
  '2#_': `(Shach s.k. 4) The Gaon z"l expanded to challenge my elder Maharam Isserles on what Rama wrote in this siman: "and according to what will be explained shortly," etc. — and he challenged him in s.k. 4; and Taz also expanded and challenged him; and both intended one matter; and to my humble opinion their words are wondrous in my eyes — for from the Rosh's and Rabbeinu Yerucham's words it is proven explicitly that the majority of the cavity of the opening of the kaneh is more than what is asked on a bird: if we estimate as an issur according to animal proportion — then there would be a great stringency for a bird, since it is a very small measure; therefore we estimate in a bird by the majority of the width of the cavity of the opening of the kaneh — thus Beit Yosef; and the Rosh explains his words: wherever we estimate in an animal by a majority — likewise in a bird we estimate by a majority; and wherever we estimate in an animal as an issur — he need not ask on a bird what is obvious that we estimate according to its smallness; but regarding knafah puncture where we estimate the intact portion with the punctures as an issur when they are close like sieve punctures destined to be deficient — that is what he asks on a bird: for when estimating the measure of deficiency not proportionate to the animal's issur — its measure of deficiency is very small; do we be stringent at such a small measure to combine the intact portion with the deficiency? — and he answers: no — only another measure the Sages gave: "one folds it and places it on the opening of the kaneh" — end; and Rabbeinu Yerucham wrote these matters with some expansion of explanation: if the kaneh was punctured in a bird knafah-style — punctures with deficiency — in an animal its measure is like an issur; and if you estimate thus in a bird you will not find in it an issur, for the entire bird's kaneh is not like an issur; and if you say everything according to large and small — its measure of deficiency would be very small; and if you say estimate the issur according to large and small and consider in this the intact portion between puncture and puncture with the deficiency of the punctures — there would be a great stringency; rather we estimate in a bird: one cuts below the punctures and at their sides until one can fold the strap with the punctures and place it on the opening of the kaneh — if it covers between the punctures and the intact portion between puncture and puncture the majority of the cavity of the kaneh — treifah — until here Beit Yosef's language; and the Gaon z"l brings it in small seif 6 — behold explicitly as his words. And what the Gaon proved from Rabbeinu Yerucham's words: "and the first appears primary," etc. — is according to his method in what he wrote initially that an issur is more than the majority of the cavity of the opening of the kaneh; but according to what I wrote there is no such thing — the majority is more; yet this may be challenged on Rabbeinu Yerucham's words: "and some explain a bird whose life-force is not so great as an animal — we do not estimate it as an issur even if in its width there is an issur; on the contrary, because its life-force is small — it should be estimated as an issur since it is a small measure" — one may say thus: according to the first explanation — in a large bird we estimate like in an animal; he meant: we estimate by proportion; and it teaches us: do not say since in a bird there is nothing to estimate as an issur because it is very small — likewise in a large bird; it teaches us we estimate by proportion; and some hold: in a bird whose life-force is not so great as an animal — we do not estimate as an issur but by the width of the cavity of a small bird's kaneh; and we do not distinguish large bird and small — examine. And this difficulty I challenged in my youth to the Gaon z"l; and this was his written reply yesterday: I studied what my son Moshe challenged — about three hours at night; and I saw that what my son-in-law answered (that even in an animal the issur is larger than a majority, but in a bird the majority is larger than its issur) — this is not so (from Rashba who learns in an animal we estimate by majority stringently from bird; and Beit Yosef brings it; and according to my son-in-law — whence do we know bird is different? — examine); but I wished to say Rashba and the Mechaber disagree with the Rosh and Rabbeinu Yerucham in small seif 7; but now I arose at dawn about two hours and saw he challenged nothing; and it is clear to me like the sun at noon that truth is with me — therefore you too be precise and aim at truth — end. And behold I spoke with the Gaon mouth to mouth — thus is the explanation of the Rosh and Rabbeinu Yerucham: always an issur is more than the majority of the cavity; and "very small," etc., he meant: since we have no known measure in a small bird how much its deficiency will be, but we estimate according to the proportion of the animal's measure — and in a very small bird impossible to estimate by proportion to a large animal so that the measure in the small bird would be its narrow measure; and perforce we need be stringent to a lesser measure proportionate to very small; and this is a great stringency; and I challenged him: where did the Rosh write "and wherever we estimate in animal as an issur," etc. — "we estimate according to its smallness" — see there — implies we estimate; and according to the Gaon's words — where do we estimate, since impossible to narrow as mentioned above? And what he answered me: it is not so regarding deficiency in one place — one cannot estimate it, only we are stringent even more than its measure even in very small, since punctured in one place; unlike knafah puncture — there are two stringencies: one that impossible to estimate so much; and must be the puncture less than an issur; and we are stringent that the intact portion between punctures must combine — if so it is two stringencies and a great stringency: what cannot be estimated and also must count the intact portion between punctures — until here his words; and I challenged his words: one, from the Rosh's words it does not imply thus; and further, the Talmud sages could estimate; and further difficult is the Rosh's challenge on Rif's explanation in a bird: what? — it refers to deficiency — what is the question on a bird? — how do we estimate more than other issurim such as deficiency of skull for Beit Shammai as a full drill and for Beit Hillel as a sela — see there; and according to the Gaon we are different here because impossible to estimate — but certainly they could estimate; and further difficult: according to the Gaon's answer — because impossible — what did the Talmud sages give us the measure of the majority of the cavity of the opening — a measure less than an issur — so we would know to estimate? If so they should have given us a measure more than the majority of the cavity of the kaneh and less than an issur proportionately; and so we find they dispute in siman 48 whether like a sela or more than a sela; and similarly the Gaon challenged in siman 30 s.k. 20 in Siftei Kohen — see there (and also according to what I wrote the measure of an issur implies it is very small); and still requires examination.`,
});

// --- pitchei-teshuva (2) ---
patchFile('siman_034/pitchei-teshuva/part-001.txt', 'pitchei-teshuva', {
  '1#_': `It is forbidden. [Avnei Nezer and see Levushei Sarad who was in doubt: perhaps that it becomes nevelah is specifically when the gargeret is severed in its majority; but in the law of deficiency of gargeret in seif 2 whose measure is like an issur — even though the majority is intact — it is not nevelah; and even though Rambam wrote in all laws of deficiency that it is nevelah — one may say he wrote so for his own reason; but according to Tosafot chapter 1 daf 43 s.v. "those treifot of deficiency of gargeret" — only on account of its end — its end is to be severed in its majority; if so one may say: since now the gargeret is still healthy — his slaughter is valid slaughter and purifies from nevelah; and all the more it is not nevelah from life, etc.; and he raised again that also deficiency of gargeret is likewise nevelah like severance of gargeret; and even in the law in seif 3 of many punctures with deficiency where the intact portion between them combines to issur — also nevelah, even though what we hold that the intact portion combines is because its end will be removed and then it will be like an issur and then its end will be severed in its majority; if so this is judged twice on account of its end; nevertheless its law is like severance; and there is a practical difference whether it is nevelah regarding orlah that applies to treifah and not to nevelah (as above siman 16 s.k. 9); but eggs of such a chicken — their law is like the law of an egg of treifah forbidden d'oraisa, and not like an egg of nevelah forbidden only d'rabbanan; and likewise an egg of punctured esophagus and actual severance of gargeret is d'oraisa — see there.]`,
  '2#_': `Specifically. [In responsa Chasam Sofer end siman 48 he wrote on this and thus: examine from below siman 49 s.k. 4 and Taz there; and what he answered in Knesset HaGedolah there — that in the esophagus thorns are common does not apply here; and there is no reason to distinguish — that in the esophagus presumption of prohibition applies and we do not say safek that it is not, as written in responsa (siman 25) brought above siman 33 s.k. 4 — end.]`,
});

// --- yad-avraham (3) ---
patchFile('siman_034/yad-avraham/part-001.txt', 'yad-avraham', {
  '1#_': `(Siman 34 seif 2) We are not expert in the measure of an issur; therefore we estimate it by the majority of the width of the cavity of the kaneh. Taz and Shach conclude the measure of an issur is more than the majority of the cavity of the kaneh in an animal — to resolve Rama's difficulty. And Shach's words are difficult — for in s.k. 7 he brought the Rosh's and Rabbeinu Yerucham's words that prove explicitly the opposite — that the measure of an issur is less than the majority of the cavity in an animal; for they wrote in the bird's question: many punctures and he asks — in an animal its measure is like an issur, and in a bird there is not in its gargeret like an issur; and if we estimate according to the proportion of the measure in an animal — its measure of deficiency would be very small; and if the intact portion combines — there would be a great stringency; therefore we estimate by covering the majority of its kaneh's cavity — end. And if you say the measure of an issur in an animal is more than its majority of cavity — then according to the proportion of this measure in a bird also it is more than the majority of its kaneh's cavity — and how did they write that if estimated by proportion of issur in animal its deficiency measure would be very small? Proven explicitly the measure of an issur in an animal is less than the majority of its cavity; and if so by proportion in a bird also it is smaller than the majority of its kaneh's cavity; therefore we estimate by covering the majority of its kaneh's cavity, which is less than its deficiency measure by proportion. And in one puncture we estimate by proportion which is less than this, as Rama hagahah s.k. 4 in name of "some say." And Shach did not notice this; and what Shach wrote in s.k. 4 that so it is proven in Rabbeinu Yerucham that the measure of an issur is more than a majority — there is no such thing, for he wrote explicitly as stated — and examine.`,
  '2#_': `(Seif 4 in hagahah) And if a gargeret of a bird was deficient — some say we estimate like knafah puncture (Rif and Rambam). I have proof for their words from the Yerushalmi chapter 3 of Niddah: R' Zeira in name of Shmuel — an incident came before R' Yosi: one year it was punctured a full needle; and he answered: do we not know which is its majority? — end; and hence they were doubtful whether we estimate puncture by proportion of issur measure in an animal; and it is possible to estimate; and he answered there is no concern — for by its majority we estimate, and this we know — and understand.`,
  '3#_': `(Seif 9) Found a gargeret severed and unknown if from life, and cannot attribute that because of slaughter he slaughtered in two places. Implies if one can attribute it happened from slaughter in two places — we attribute and it is kosher; even though according to Rama's hagahah siman 23 that delay disqualifies in any amount in animal and bird; and likewise per the Mechaber end siman 21 that a bird's delay is minimal — if so impossible to permit slaughter in two places unless he knows it did not delay at all, as acharonim end siman 21; nevertheless here it seems permitted because of safek after slaughter it happened without slaughter in two places. (You may say: because he slaughtered in two places — perhaps after completing slaughter of most of the two signs he slaughtered again in the kaneh above or below; and furthermore this is extra stringency to disqualify for any delay, and in safek we are not stringent — and understand; and see acharonim siman 23 and end siman 21.) Shalom.`,
});

// --- kaf-hachayim (10) ---
patchFile('siman_034/kaf-hachayim/part-001.txt', 'kaf-hachayim', {
  '1#_': `(1) [Seif 1] If the gargeret was severed — the majority of its cavity, etc. The wall of the kaneh is thick from above and at the side of the neck it is only a thin membrane, and it is not forbidden until the majority of the cavity is severed; and the thickness of the wall of the kaneh does not complete to a majority — so in the Talmud; and Shach s.k. 1. Peri Chadash ot 1, Levush ot 1, Bayit Chadash ot 1; and likewise if severed from below upward so there is a majority of its cavity — even though the majority of thickness remains — treifah. Peri Chadash there. Zivchei Tzedek ot 1; however in the large ring the majority of the circumference is the majority of the cavity. Rashdam. Zivchei Tzedek there; and he meant because all is thick and not like the kaneh at the side of the neck which is thin; and see above siman 21 ot 1.`,
  '2#_': `(2) Incident that they brought before us a chicken after slaughter and saw in the kaneh below the place they slaughtered one place where the gargeret was removed — meaning the hard ring — and nothing remained except the membrane connecting them — the soft membrane before the rings, called kaneh as above siman 21 ot 1; and that membrane was whole on every side with no defect; and it appeared so from the beginning of its creation; and we declared it kosher as Maran z"l wrote we require majority of its cavity — and here the entire cavity was intact; and as Tur z"l wrote: if the majority of its cavity was not severed — even if it is majority of circumference, etc. — kosher — see there; and although the entire ring was missing — it matters not, for halachah is as those who say majority of its cavity; and we permitted publicly. Zivchei Tzedek ot 1.`,
  '3#_': `(3) There. Or above this, etc. Meaning above the place fit for slaughter as well — the law is thus that the gargeret is severed in its majority; but below the place fit for slaughter — in any amount — treifah, as below seif 8. Beit Yosef. Taz s.k. 1. Shach s.k. 2. Peri Chadash ot 2, Levush ot 2 and ot 3, Bayit Chadash ot 2, Sha'arei Tzedek ot 2, Zivchei Tzedek ot 2, Bayit Yitzchak ot 1; and see above siman 20 seif 1 what place is called below the measure of slaughter in bird and animal — see there.`,
  '4#_': `(4) And if severed in several places — they combine to a majority; not only in one circumference — this is simple from the law of punctured punctures without deficiency in seif 3; but even one above another and below on another side also combine. Turei Zahav ot 1, Pri Megadim siman 8 ot 5.`,
  '5#_': `(5) And know that all the laws until seif 7 apply even above the place of slaughter — so Bach in name of Orach Chaim. Turei Zahav there. Sha'arei De'ah ot 2, Bayit Yitzchak in Tevu'ot Shor ot 1.`,
  '6#_': `(6) [Seif 2] If punctured with a puncture that has deficiency like an issur, etc. Hagahah: and according to what will be explained shortly, etc. Therefore it appears he meant the majority of the width of a bird's kaneh's cavity, etc.; see Taz s.k. 3 and Shach s.k. 4 who disagree with our rabbi's words cited and hold we estimate by the majority of the width of an animal's kaneh's cavity — see there; but Turei Zahav ot 2 agreed with our rabbi z"l that we estimate in a bird's kaneh — see there; and Bayit Yitzchak ot 5, Pri Megadim siman 8 ot 7 agreed. Turei Zahav siman 38 ot 6; and Turei Zahav ot 7 further wrote we estimate in a medium bird and goose — and similar is called medium — see there; and so Bayit Yitzchak in Amud HaMa'ariv ot 9, Pri Megadim there.`,
  '7#_': `(7) [Seif 3] If punctured around its circumference thin punctures, etc. Meaning specifically punctured around its circumference exactly; but punctures without deficiency along the length of the kaneh do not combine to the majority of the circumference — for it would only be as split; therefore punctures without deficiency never disqualify except when standing on the gargeret's circumference in its majority. Shach s.k. 5. Levush ot 5, Zivchei Tzedek ot 8, Bayit Yitzchak ot 4.`,
  '8#_': `(8) There. And if they have deficiency they combine to an issur, etc. From that he wrote regarding punctures with deficiency — if there is an issur in the punctures with the intact portion between them, etc. — and did not likewise write at the beginning regarding punctures without deficiency that the intact portion between them combines to a majority — implies he holds in punctures without deficiency the intact portion does not combine even if there is not between puncture and puncture a full puncture; and it also implies there is no distinction between animal and bird regarding combining the intact portion — only in punctures with deficiency: even in an animal the intact portion combines to an issur when there is not between puncture and puncture a full puncture; and when there is no deficiency — even in a bird the intact portion does not combine to the majority of its gargeret's circumference. Shach s.k. 6. Levush ot 6, Bayit Chadash ot 4, Kereti ot 8; and he wrote not like Peri Chadash. And so Eshel Avraham ot 1, Turei Zahav there ot 5; but Turei Zahav ot 4 agreed like Peri Chadash that even in punctures without deficiency that combine to a majority — the intact portion between them also combines if there is not between puncture and puncture a full puncture — see there; and so Bayit Yitzchak ot 5, Pri Megadim siman 8 ot 8, Pri Megadim ot 1; except he wrote there Pri Megadim: in practical ruling one may be lenient like Shach and his colleagues.`,
  '9#_': `(9) There. And if they have deficiency they combine to an issur — whether along its length or around the circumference. Levush; and this is when there is not between puncture and puncture a full puncture — for otherwise they do not combine, for it is clear.`,
  '10#_': `(10) [Seif 4] In a bird, if punctured knafah-style one cuts the place, etc. Meaning punctures with deficiency — whose measure in an animal is like an issur, and in a bird there is not in its gargeret like an issur; and if estimated according to proportion of issur measure in animal — its deficiency measure would be very small; and when the intact portion between them also combines — there would be a great stringency; therefore its measure is by if it covers, etc.; but in punctures without deficiency — since we require they stand on the gargeret's circumference — there is no distinction between animal and bird, for always each combines the majority of its gargeret's circumference — so Rosh and Rabbeinu Yerucham. Shach s.k. 7. Peri Chadash ot 6, Zivchei Tzedek ot 11; and see above ot 6.`,
});

// --- kol-yaakov (10) — Hebrew source is tefillin cross-reference material; translated as written ---
patchFile('siman_034/kol-yaakov/part-001.txt', 'kol-yaakov', {
  '1#_': `A) Seif 1. Order of placement, etc. Kadesh on the left of the placer, etc. And even if the placer is left-handed — we do not follow his right and left but the reader's right and left — meaning every person's right and left. Magen Avraham s.k. 1, Pri Megadim Eshel Avraham ot 1, Raz Siman ot 1, Kaf HaChayim siman 22 ot 1, and so in shin-yud one places Kadesh head toward the left side — more toward the world's left toward the outside so it is read in order; and for a left-handed person Kadesh head more to the left and inward — the placer's outside. Pri Megadim there.`,
  '2#_': `B) There: "And after that, when He brings you," etc. And if he exchanged any parshah from its designated house — invalid. Raz Siman ot 2, Maleh HaShoar kelal 19 ot 1, Kaf HaChayim there, and this is until he repairs — as stated there.`,
  '3#_': `C) There: "And for shin-dalet in the third house," etc. Nevertheless one must write them in the order they are written in the Torah; and if he changed — invalid, whether shin-yud or shin-dalet; therefore in shin-yud, which are on one parchment, one writes Kadesh and V'haya ki y'viacha and leaves part of a parshah, and V'haya im shamoa, and writes parshat Shema, and afterward writes parshat V'haya im shamoa. Tur and Beit Yosef, Magen Avraham s.k. 2, Taz, Raz Siman ot 3, and so acharonim; and see our words above siman 32 ot 169.`,
  '4#_': `D) Seif 2. God-fearing person, etc., and the rest are merely straps, etc. And according to the Ari z"l — both are kodesh and one must place both together. Machberet ot 1, Chok L'Yisrael ot 2, and thus in Sha'ar HaKavanot in drushim of tefillin drush 6 on tefillin of Rabbeinu Tam z"l: know that initially my teacher z"l placed Rashi and Rabbeinu Tam tefillin together in the morning and prayed in them as he wrote z"l in Perek HaKometz — there is place on the head to place two pairs of tefillin, meaning together, for in this way there is room for a thousand pairs; and in the afternoon he placed only Rabbeinu Tam tefillin; and afterward he made a pair of Rashi tefillin per the method of Shmusha Rabbah — fingers on fingers. And their grooves are sunk to the place of the ma'avarata so each bayit is separate from its fellow; and at sewing the gid threads interrupted and passed inside the grooves from side to side; and in the morning he placed two pairs Rashi and Rabbeinu Tam, and in the afternoon this Shmusha Rabbah pair; and he said these tefillin per Shmusha Rabbah ascend in place of the two methods of Rashi and Rabbeinu Tam together — for the brains of Abba are Rabbeinu Tam tefillin and the brains of Imma are Rashi tefillin — both intermingle and become one pair of tefillin; and this is the reason they are fingers on fingers corresponding to Abba and Imma. And indeed their placement method: first insert arm tefillin per Rashi, then insert shin-yud per Rabbeinu Tam — both on the place called the kiboret of the upper section of the left arm; Rashi's higher near the shoulder, Rabbeinu Tam's lower near the middle joint; and likewise in shin-dalet place Rashi's first then Rabbeinu Tam's above Rashi's; and likewise the knot of Rashi tefillin place lower on the nape itself. The reason for placing Rashi tefillin first: initially the brains of Imma enter, then the brains of Abba which are Rabbeinu Tam tefillin, as in Azriel. Therefore when wrapping straps around the arm place Rabbeinu Tam's strap under Rashi's and cover it — only Rashi's strap is revealed; the other is covered beneath — for thus the lights of Abba are covered by the lights of Imma — end; and see what is written on this in Sefer HaKavanot Kaf HaChayim siman 27 ot 41; and Machberet ot 8 wrote in name of Ramaz z"l that Shmusha Rabbah ascends because of the two — specifically for minchah, not for shacharit — see there; and so Sefer HaKavanot Kaf HaChayim siman 37 ot 10 — see there; and further see Machberet ot 7 and Chok L'Yisrael ot 4.`,
  '5#_': `E) There: and some say if one cannot place at once — place Rashi's and bless on them, etc. And if he erred and took Rabbeinu Tam's thinking they were Rashi's and blessed and read Shema and prayed and removed them and saw they were Rabbeinu Tam's — he places Rashi's afterward and blesses on them again as his custom to bless on tefillin of Rashi. Mahariach in responsa Sam Chayim siman 1, Machberet in Chok L'Yisrael ot 1, Bayit Yitzchak in laws of Rabbeinu Tam tefillin ot 2.`,
  '6#_': `F) There: and he reads Shema in them, etc. But not Vayomer — for since tefillin are not mentioned therein it is not like false testimony. Rabbi Akiva Eiger ot 3, Raz Siman ot 5.`,
  '7#_': `G) Seif 3. One should not do so except one who, etc. I wrote in my humility after seeing all acharonim' words — truth of the matter: Maran did not write one may place them only one established in piety, but per poskim' words it is only a safek; and since the ruling spread like Rashi and Rambam — one who comes to be concerned from Rabbeinu Tam's safek must be renowned in piety — not so now that our rabbi the Ari z"l revealed both are required, even if not renowned in piety one may place them, for his soul desires to fulfill the mitzvah properly; and already in the land of the deer many years most sages and their students place two pairs, and also baalei mikra and mishnah — some place two pairs. Machberet ot 2, Bayit Yitzchak there ot 3.`,
  '8#_': `H) They were accustomed to wear Rabbeinu Tam tefillin at minchah per writings of Maharachav z"l; and some kabbalists of our generation in Hendzin hold otherwise — for according to their secret Rabbeinu Tam tefillin alone do not fit; nevertheless since explicitly stated the Ari z"l practiced thus before making Shmusha Rabbah tefillin, and Maharachav practiced thus — certainly their reason stands with them and we do not know. Berkei Yosef ot 2.`,
  '9#_': `I) One accustomed to wear Rabbeinu Tam tefillin alone at minchah — if he came to his pouch and found Rashi's tefillin — he may return them to the pouch and take Rabbeinu Tam's and wear them as his custom; and this is not considered "do not pass over mitzvot." Berkei Yosef ot 3.`,
  '10#_': `J) One does not bless on Rabbeinu Tam tefillin. Ran Shapira in Matzat Shemura daf 61 challenged on the measure; and correct that one does not bless on them; and the reason: Rabbeinu Tam tefillin's level is higher than Rashi's until end of Shulchan Aruch; and the Ari z"l gave reason not to bless on shin-dalet — we lack power to draw down the light emanating from the level alluded to by shin-dalet of Rashi, and all the more Rabbeinu Tam; and so Ramaz ruled not to bless; and so practiced the old rabbis of the land of Israel. Ramaz in his letters cited there siman 5; and the wondrous rabbi Maharadf brought his words in his letter Aleph-Chet siman 4. Machberet ot 3.`,
});

